export function ResetPasswordPage() {
  const { dark, toggle } = useTheme();
  const [token, setToken] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);
  const nav = useNavigate();

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setLoading(true);
    try {
      await apiFetch("/api/auth/reset-password", {
        method: "POST",
        json: { token: token.trim(), newPassword }
      });
      nav("/login", { replace: true });
    } catch (ex) {
      setErr(ex.message || "Reset failed");
    } finally {
      setLoading(false);
    }
  };

  return h("div", { className: "mx-auto max-w-md px-4 py-16" }, h(GlassPanel, {}, [
    h("h1", { className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "New password"),
    h("form", { className: "mt-6 space-y-4", onSubmit }, [
      h(Field, { label: "Reset token" }, h(TextInput, { value: token, onChange: (e) => setToken(e.target.value), required: true })),
      h(Field, { label: "New password" }, h(TextInput, { type: "password", value: newPassword, onChange: (e) => setNewPassword(e.target.value), required: true, minLength: 8 })),
      err && h("p", { className: "text-sm text-rose-400" }, err),
      h(Button, { type: "submit", className: "w-full", loading }, "Update password")
    ])
  ]));
}
